problem.answer_key:
DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_creator_id INT;
  cur_total_views INT;
  cur_tier VARCHAR(20);
BEGIN
  FOR rec IN SELECT * FROM story_events ORDER BY event_id LOOP
    SELECT status, creator_id, total_views, tier INTO cur_status, cur_creator_id, cur_total_views, cur_tier
    FROM stories WHERE story_id = rec.story_id;

    IF rec.event_type = 1 AND cur_status = 'active' THEN
      cur_total_views := cur_total_views + rec.view_count;
      IF cur_total_views >= 1000 THEN
        cur_tier := 'viral';
      END IF;
      UPDATE stories SET total_views = cur_total_views, tier = cur_tier WHERE story_id = rec.story_id;
    ELSIF rec.event_type = 2 AND cur_status = 'active' AND rec.requester_id = cur_creator_id THEN
      UPDATE stories SET status = 'archived' WHERE story_id = rec.story_id;
    ELSIF rec.event_type = 3 AND cur_status = 'archived' AND rec.requester_id = cur_creator_id THEN
      UPDATE stories SET status = 'active', tier = 'standard' WHERE story_id = rec.story_id;
    END IF;
  END LOOP;
END $$;

SELECT * FROM stories ORDER BY story_id;
